  "scene": "小有成就、尾巴开始翘的时候",
  "text": "君子泰而不骄；小人骄而不泰。",
  "source": "子路篇",
  "translation": "君子安泰舒展而不骄傲凌人，小人骄傲凌人却内心不安。",
